#!/usr/bin/env bash
# /* ---- 💫 https://github.com/0o0-ct/Pixi-Arch-A 💫 ---- */  ##
# SafeModeRecovery.sh — carga automática de la config real en Safe Mode
#
# Hyprland 0.57: si el compositor muere "not-cleanly" al arrancar,
# start-hyprland lo reinicia con --safe-mode. En Safe Mode la config real
# NO se carga: getMainConfigPath() devuelve <instance>/recoverycfg.lua
# (config de ejemplo, ~30 binds y autogenerated=1) y hay que pulsar
# "Load config" a mano. Ese botón hace: m_safeMode = false + Config::mgr()->reload().
#
# Este script emula ese botón sin tocar el binario:
#   1. detecta Safe Mode (binds < umbral Y autogenerated == 1)
#   2. symlink <instance>/recoverycfg.lua -> hyprland.lua real
#      (así reload() verifica la sintaxis del fichero real en la fase 1)
#   3. hyprctl reload → limpia binds/reglas/monitores y ejecuta la config
#   4. verifica los binds reales (~192) y cierra el diálogo Safe Mode
#      (si hyprland-dialog muere sin imprimir opción, Hyprland cierra
#      la caja silenciosamente — ver src/helpers/AsyncDialogBox.cpp)
#
# Se lanza desde ~/.config/autostart/pixi-safe-recovery.desktop vía
# systemd-xdg-autostart-generator: corre independientemente de si la config
# de Hyprland llegó a cargar, por eso también funciona en Safe Mode.
#
# Overrides (solo para pruebas):
#   PIXI_RECOVERY_REAL_CFG  config real (def: ~/.config/hypr/hyprland.lua)
#   PIXI_RECOVERY_BINDS     umbral de binds (def: 100)
#   PIXI_RECOVERY_POLL      segundos entre chequeos (def: 3)
#   PIXI_RECOVERY_IDLE_EXIT segundos sin instancia antes de salir (def: 120)
#   PIXI_RECOVERY_MAX       segundos totales máximos; 0 = sin límite (def: 0)

set -u

RUNTIME="${XDG_RUNTIME_DIR:-/run/user/$(id -u)}"
REAL_CFG="${PIXI_RECOVERY_REAL_CFG:-$HOME/.config/hypr/hyprland.lua}"
THRESHOLD="${PIXI_RECOVERY_BINDS:-100}"
POLL="${PIXI_RECOVERY_POLL:-3}"
IDLE_EXIT="${PIXI_RECOVERY_IDLE_EXIT:-120}"
MAX_SECONDS="${PIXI_RECOVERY_MAX:-0}"
MAX_ATTEMPTS=5

log() {
  logger -t pixi-safe-recovery -- "$*" 2>/dev/null || true
  printf '%s [SafeModeRecovery] %s\n' "$(date '+%H:%M:%S')" "$*"
}

if [ ! -f "$REAL_CFG" ]; then
  log "ERROR: no existe el config real: $REAL_CFG"
  exit 1
fi

# nº de binds de la instancia $1; -1 si la instancia no responde
count_binds() {
  local out rc
  out="$(hyprctl -i "$1" binds -j 2>/dev/null)"
  rc=$?
  if [ "$rc" -ne 0 ]; then
    printf '%s' "-1"
    return
  fi
  if command -v jq >/dev/null 2>&1; then
    printf '%s' "$out" | jq -r 'if type == "array" then length else -1 end' 2>/dev/null || printf '%s' "-1"
  else
    printf '%s' "$out" | grep -c '"key":'
  fi
}

# 1 si la instancia $1 tiene la config de ejemplo (Safe Mode)
is_autogenerated() {
  local v
  v="$(hyprctl -i "$1" getoption autogenerated -j 2>/dev/null | jq -r '.int // -1' 2>/dev/null)"
  [ "$v" = "1" ]
}

to_num() {
  case "$1" in
  '' | *[!0-9]*) printf '%s' "-1" ;;
  *) printf '%s' "$1" ;;
  esac
}

start_ts=$(date +%s)
current_sig=""
attempts=0
attempt_sig=""
idle=0
zero_since=0
zero_warned=0

log "vigilancia iniciada (umbral=${THRESHOLD} binds, config=${REAL_CFG})"

while true; do
  now=$(date +%s)
  if [ "$MAX_SECONDS" -gt 0 ] && [ $((now - start_ts)) -ge "$MAX_SECONDS" ]; then
    log "límite de tiempo alcanzado: fin de la vigilancia"
    exit 0
  fi

  # Buscar la instancia viva más reciente. Los directorios de instancias
  # muertas dejan sockets residuales, por eso se comprueba que hyprctl
  # responda (exit 0) antes de darla por viva.
  target=""
  while IFS= read -r d; do
    [ -n "$d" ] || continue
    [ -S "$RUNTIME/hypr/$d/.socket.sock" ] || continue
    if hyprctl -i "$d" binds -j >/dev/null 2>&1; then
      target="$d"
      break
    fi
  done < <(ls -1t "$RUNTIME/hypr" 2>/dev/null)

  if [ -z "$target" ]; then
    idle=$((idle + POLL))
    if [ "$idle" -ge "$IDLE_EXIT" ]; then
      log "sin instancia Hyprland durante ${idle}s: fin de la vigilancia"
      exit 0
    fi
    sleep "$POLL"
    continue
  fi
  idle=0

  if [ "$target" != "$current_sig" ]; then
    current_sig="$target"
    attempts=0
    attempt_sig=""
    zero_since=0
    zero_warned=0
    log "vigilando instancia: $current_sig"
  fi

  binds="$(to_num "$(count_binds "$current_sig")")"

  # Instancia viva pero sin binds: la config aún no cargó (o está rota).
  if [ "$binds" -eq 0 ]; then
    if [ "$zero_since" -eq 0 ]; then
      zero_since=$now
    elif [ "$zero_warned" -eq 0 ] && [ $((now - zero_since)) -ge 120 ]; then
      log "AVISO: la instancia lleva 120s sin binds (¿config rota?)"
      zero_warned=1
    fi
    sleep "$POLL"
    continue
  fi
  zero_since=0
  zero_warned=0

  # Sesión sana (config real cargada): solo vigilar.
  if [ "$binds" -ge "$THRESHOLD" ] 2>/dev/null; then
    sleep "$POLL"
    continue
  fi

  # binds fuera de rango inesperado (instancia muriendo, etc.): reintentar.
  if [ "$binds" -lt 0 ]; then
    sleep "$POLL"
    continue
  fi

  # ---- Candidato a Safe Mode: confirmar con autogenerated=1 ----
  if ! is_autogenerated "$current_sig"; then
    # Config real con pocos binds (o estado transitorio): no tocar nada.
    sleep "$POLL"
    continue
  fi

  if [ "$attempt_sig" = "$current_sig" ] && [ "$attempts" -ge "$MAX_ATTEMPTS" ]; then
    log "AVISO: safe mode persistente tras $attempts intentos (binds=$binds); pulsa 'Load config' a mano"
    sleep "$POLL"
    continue
  fi

  attempts=$((attempts + 1))
  attempt_sig="$current_sig"
  rcfg="$RUNTIME/hypr/$current_sig/recoverycfg.lua"

  log "Safe Mode detectado (binds=$binds, autogenerated=1): intento $attempts/$MAX_ATTEMPTS"

  # Apuntar recoverycfg.lua al config real (symlink: cada reload relee el real)
  if ! ln -sfn "$REAL_CFG" "$rcfg" 2>/dev/null; then
    log "ERROR: no se pudo crear el symlink $rcfg"
    sleep "$POLL"
    continue
  fi

  if [ "$attempts" -ge 2 ]; then
    # reintento con el estado de config por completo nuevo
    hyprctl -i "$current_sig" reload full-reset >/dev/null 2>&1 ||
      hyprctl -i "$current_sig" reload >/dev/null 2>&1
  else
    hyprctl -i "$current_sig" reload >/dev/null 2>&1
  fi

  sleep 2
  binds2="$(to_num "$(count_binds "$current_sig")")"

  if [ "$binds2" -ge "$THRESHOLD" ] 2>/dev/null; then
    log "¡Config real cargada! (binds $binds → $binds2)"
    # Cerrar el diálogo Safe Mode: hyprland-dialog muere sin imprimir opción
    # y Hyprland cierra la caja silenciosamente.
    if pkill -x hyprland-dialog 2>/dev/null; then
      log "diálogo Safe Mode cerrado"
    fi
    attempts=0
    attempt_sig=""
  else
    log "el reload no surtió efecto (binds=$binds2); se reintentará"
    sleep 10
  fi

  sleep "$POLL"
done
